import test from 'node:test';import assert from 'node:assert/strict';import {IDBFactory} from 'fake-indexeddb';
import {putDraft,getDraft,savePaperDraft,getSnapshot,putSnapshot,putLocalBlob,listLocalBlobs,listSnapshots,queueLocalDrafts,listMutations,notebookDeletionKey,localBlobDigest,type Draft} from '../pwa/src/storage.ts';
import {applyPaperCommand,blankPage,migratePaper,notebookDocumentId,legacyPaperPhotoIdentities,type PaperDocument} from '../src/lib/notebookDocument.ts';
import {paperMarkdown} from '../src/lib/paperArchiveMetadata.ts';import {verifyPaperCollaboration} from '../src/lib/paperCollaboration.ts';
import {preflightPaperLegacy,commitPaperLegacyPreflight,reconcilePaperLegacy,paperLegacyReceiptKey,stagePaperLegacyMirror,publishPaperLegacyMirror} from '../src/lib/paperLegacyBridge.ts';
import {noteBoardId,photoReference,parsePhotoReference} from '../src/lib/notebook.ts';import {paperLegacyOwnerKey,migrateOwnedPaperNotebook} from '../src/lib/paperLegacyMigration.ts';
import {scanLegacyPaperImages} from '../src/lib/paperLegacyImages.ts';
const now='2026-10-13T12:00:00.000Z',current=()=>true,scope={accountId:'bridge-test',spaceId:'year-one'};
const key=(id:string)=>`${scope.accountId}|${scope.spaceId}|whiteboard|${notebookDocumentId(id)}`;
const stroke=(id:string,x=10)=>({id,color:'#1144cc',width:3,points:[{x,y:20,pressure:.3},{x:x+10,y:30,pressure:.7}]});
async function seed(id:string,options:{migration?:boolean;board?:unknown;currentText?:string}={}){
 globalThis.indexedDB=new IDBFactory();const board=options.board??null,source=migratePaper(id,'Original',board,now),identity={...scope,type:'whiteboard' as const,documentId:notebookDocumentId(id)};
 const old=board?{...scope,type:'whiteboard' as const,documentId:source.legacy.boardId,title:'Old board',content:board,baseVersion:4,updatedAt:10,syncState:'synced' as const}:null;
 if(old)await putDraft(old);
 const content=options.currentText?applyPaperCommand(source,{type:'patch-object',id:source.objects[0].id,patch:{markdown:options.currentText}},now):source;
 const draft:Draft={...identity,title:'QA',content,baseVersion:2,updatedAt:1,syncState:'synced'};
 if(options.migration===false)await putDraft(draft);else await savePaperDraft(draft,null,{markdown:'Original',legacy:old,migratedAt:now});
 const metadata:Draft={...scope,type:'notesMarkdown',documentId:id,title:'QA',content:{id,title:'QA',markdown:'Original'},baseVersion:3,updatedAt:1,syncState:'synced'};await putDraft(metadata);return {source,content,draft:await getDraft(draft),old,metadata};
}
async function incoming(metadata:Draft,markdown:string){const next={...metadata,content:{...(metadata.content as object),markdown},updatedAt:100};await putDraft(next);return next;}
test('A late old text update is atomically reconciled with Yjs, receipt, source history and unchanged migration',async()=>{
 const id='qa-bridge-update',{metadata}=await seed(id),migration=await getSnapshot(`paper-migration|${key(id)}`);await incoming(metadata,'Updated **old-client text**');const result=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'Updated **old-client text**',metadataAuthority:'indexeddb',current,now});
 assert.equal(result.changed,true);assert.equal(result.recovered,false);assert.equal(paperMarkdown(result.draft.content as PaperDocument),'Updated **old-client text**');verifyPaperCollaboration(result.draft.content as PaperDocument);assert.deepEqual(await getSnapshot(`paper-migration|${key(id)}`),migration);assert.equal(result.draft.syncState,'local');assert.equal((await getSnapshot(paperLegacyReceiptKey(scope,id)))?.value.observed.markdown,'Updated **old-client text**');assert.ok((await listSnapshots(scope.accountId,scope.spaceId)).some(row=>row.key.startsWith('paper-legacy-recovery|')));
 await queueLocalDrafts(scope.accountId,scope.spaceId);assert.ok((await listMutations(scope.accountId,scope.spaceId)).some(row=>row.documentId===notebookDocumentId(id)));
});
test('Concurrent old/new text is preserved once; replay cannot add more recovery pages',async()=>{
 const id='qa-bridge-concurrent',{metadata,content}=await seed(id,{currentText:'Current **choice**'});await incoming(metadata,'Incoming **choice**');const result=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'Incoming **choice**',current,now});const document=result.draft.content as PaperDocument;assert.equal(result.recovered,true);assert.equal(document.pages.length,2);assert.equal(document.objects[0].markdown,'Current **choice**');assert.ok(document.objects.some(o=>o.markdown==='Incoming **choice**'));assert.equal(document.legacy.markdown,content.legacy.markdown);
 const again=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'Incoming **choice**',current,now});assert.equal(again.changed,false);assert.equal((again.draft.content as PaperDocument).pages.length,2);assert.equal((again.draft.content as PaperDocument).revision,document.revision);
});
test('Absent historical baseline retains a different incoming contribution separately',async()=>{
 const id='qa-bridge-no-baseline',{metadata}=await seed(id,{migration:false});await incoming(metadata,'New source with no historical receipt');const result=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'New source with no historical receipt',current,now});assert.equal(result.recovered,true);assert.equal((result.draft.content as PaperDocument).objects[0].markdown,'Original');assert.ok((result.draft.content as PaperDocument).objects.some(o=>o.markdown==='New source with no historical receipt'));assert.equal(result.receipt.baselineKnown,false);
});
test('Partitioned reading order identical to incoming metadata does not become a duplicate page',async()=>{
 const id='qa-bridge-partition',{draft,source,metadata}=await seed(id),page=blankPage('qa-part-two'),document=applyPaperCommand(draft!.content as PaperDocument,{type:'batch',commands:[{type:'patch-object',id:source.objects[0].id,patch:{markdown:'First current part',textPartition:'qa-partition'}},{type:'insert-page',page},{type:'upsert-object',object:{...source.objects[0],id:'qa-part-two-text',pageId:page.id,markdown:'Second current part',textPartition:'qa-partition'}}]},now);await putDraft({...draft!,content:document});const text=paperMarkdown(document);await incoming(metadata,text);
 const result=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:text,current,now});assert.equal(result.changed,false);assert.equal((result.draft.content as PaperDocument).pages.length,2);assert.equal(paperMarkdown(result.draft.content as PaperDocument),text);
});
test('A removed legacy root never replaces current pages when a new old-client contribution arrives',async()=>{
 const id='qa-bridge-removed',{draft,source,metadata}=await seed(id),page=blankPage('qa-survivor'),document=applyPaperCommand(draft!.content as PaperDocument,{type:'batch',commands:[{type:'insert-page',page},{type:'upsert-object',object:{...source.objects[0],id:'qa-survivor-text',pageId:page.id,markdown:'Surviving current text'}},{type:'remove-page',id:source.pages[0].id}]},now);await putDraft({...draft!,content:document});await incoming(metadata,'New legacy contribution');const result=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'New legacy contribution',current,now});assert.equal(result.recovered,true);assert.ok((result.draft.content as PaperDocument).objects.some(o=>o.markdown==='Surviving current text'));assert.ok((result.draft.content as PaperDocument).objects.some(o=>o.markdown==='New legacy contribution'));
});
test('Graph and source metadata changes both invalidate preflight without committing a stale receipt',async()=>{
 const id='qa-bridge-cas',{draft,metadata,source}=await seed(id);await incoming(metadata,'Incoming');const plan=await preflightPaperLegacy({noteId:id,scope,incomingMarkdown:'Incoming',current,now});await putDraft({...draft!,content:applyPaperCommand(source,{type:'patch-object',id:source.objects[0].id,patch:{markdown:'Concurrent after preflight'}},now)});await assert.rejects(()=>commitPaperLegacyPreflight(plan,current));assert.equal(await getSnapshot(paperLegacyReceiptKey(scope,id)),undefined);assert.equal(paperMarkdown((await getDraft(draft!))?.content as PaperDocument),'Concurrent after preflight');
 const fresh=await preflightPaperLegacy({noteId:id,scope,incomingMarkdown:'Incoming',current,now});await incoming(metadata,'Third source');await assert.rejects(()=>commitPaperLegacyPreflight(fresh,current));assert.equal(await getSnapshot(paperLegacyReceiptKey(scope,id)),undefined);
});
