test('Long photo aliases preserve original bytes and copy a scoped managed asset with accurate media metadata',async()=>{
 const id='qa-bridge-long-photo';await seed(id);const sourceId='photo-'.repeat(50),raw={photos:[{id:sourceId,name:'Original JPEG'}]},assetId=legacyPaperPhotoIdentities(id,raw)[0].assetId,bytes=new Blob(['qa-original-bytes'],{type:'image/jpeg'});await putLocalBlob({...scope,id:sourceId,documentId:`note-${id}`,name:'Original JPEG',blob:bytes,createdAt:1,status:'pending'});await putDraft({...scope,type:'whiteboard',documentId:`note-${id}`,title:'Old photos',content:raw,baseVersion:1,updatedAt:1,syncState:'synced'});
 const result=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'Original',current,now}),files=await listLocalBlobs(scope.accountId,scope.spaceId),managed=files.find(file=>file.id===assetId)!;assert.notEqual(assetId,sourceId);assert.equal(await managed.blob.text(),'qa-original-bytes');assert.equal(await files.find(file=>file.id===sourceId)!.blob.text(),'qa-original-bytes');const asset=(result.draft.content as PaperDocument).assets.find(a=>a.id===assetId)!;assert.equal(asset.size,bytes.size);assert.equal(asset.mediaType,'image/jpeg');assert.equal(managed.removedFromNote,false);
});
