test('A staged native mirror resumes idempotently and becomes observed only after explicit confirmation',async()=>{
 const id='qa-bridge-native-mirror';await seed(id,{currentText:'Current notebook'});await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'Original',current,now});const ticket=await stagePaperLegacyMirror({noteId:id,scope,expectedMarkdown:'Original',desiredMarkdown:'Current notebook',current,now}),again=await stagePaperLegacyMirror({noteId:id,scope,expectedMarkdown:'Original',desiredMarkdown:'Current notebook',current,now});assert.equal(again.receipt.mirror?.id,ticket.receipt.mirror?.id);assert.equal(ticket.receipt.observed.markdown,'Original');await assert.rejects(()=>publishPaperLegacyMirror(ticket,{current,confirmedMarkdown:'Not confirmed',now}));
 const published=await publishPaperLegacyMirror(ticket,{current,confirmedMarkdown:'Current notebook',now});assert.equal(published.receipt.observed.markdown,'Current notebook');assert.equal(published.receipt.mirror?.status,'published');const replay=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'Current notebook',current,now});assert.equal(replay.changed,false);assert.equal((replay.draft.content as PaperDocument).pages.length,1);
});
