 const id='qa-bridge-remote-ambiguous',{draft,metadata}=await seed(id),old=await oldPhoto(id,[{id:'same',serverId:'server-one'},{id:'same',serverId:'server-two'}]),raw=`Original\n\n![Ambiguous](${photoReference(old.documentId,'same')})`;await incoming(metadata,raw);let calls=0;await assert.rejects(()=>reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:raw,current,now,downloadOriginal:async()=>{calls++;return new Blob([imageBytes],{type:'image/png'});}}));assert.equal(calls,0);assert.deepEqual(await getDraft(draft!),draft);assert.equal((await listLocalBlobs(scope.accountId,scope.spaceId)).length,0);assert.equal(await getSnapshot(paperLegacyReceiptKey(scope,id)),undefined);
