 globalThis.indexedDB=new IDBFactory();const id='qa-remote-initial-offline',raw=`Original\n\n![Remote](${photoReference(noteBoardId(id),'remote')})`,metadata:Draft={...scope,type:'notesMarkdown',documentId:id,title:'Keep title',content:{id,markdown:raw},baseVersion:3,updatedAt:1,syncState:'synced'};await putDraft(metadata);const old=await oldPhoto(id,[{id:'remote',serverId:'server-original',name:'Remote.png',mediaType:'image/png',size:imageBytes.length}]);let calls=0;
 const initial=await migrateOwnedPaperNotebook(id,raw,scope,current,{downloadOriginal:async()=>{calls++;return new Blob([imageBytes],{type:'image/png'});}}),firstIds=imageIds(initial.content as PaperDocument),files=await listLocalBlobs(scope.accountId,scope.spaceId),baseline=(await getSnapshot(`paper-migration|${key(id)}`))!;assert.equal(calls,1);assert.equal(files.length,1);
 const replay=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:raw,current,now});assert.equal(replay.changed,false);assert.deepEqual(imageIds(replay.draft.content as PaperDocument),firstIds);assert.equal((replay.draft.content as PaperDocument).assets.length,1);
 const changed=raw.replace('Original','Original hors ligne');await incoming((await getDraft(metadata))!,changed);const next=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:changed,current,now});assert.equal(next.recovered,false);assert.equal(paperMarkdown(next.draft.content as PaperDocument).startsWith('Original hors ligne'),true);assert.deepEqual(imageIds(next.draft.content as PaperDocument),firstIds);assert.equal((next.draft.content as PaperDocument).assets.length,1);assert.equal((next.draft.content as PaperDocument).objects.filter(row=>row.kind==='image').length,0);assert.deepEqual(await listLocalBlobs(scope.accountId,scope.spaceId),files);assert.deepEqual(await getSnapshot(`paper-migration|${key(id)}`),baseline);assert.deepEqual(await getDraft(old),old);assert.equal(next.receipt.observed.markdown,changed);verifyPaperCollaboration(next.draft.content as PaperDocument);
