test('A new server pointer with identical bytes records its own remote provenance and reuses the proved copy offline',async()=>{
 const id='qa-bridge-remote-identical-pointer',{metadata}=await seed(id),old=await oldPhoto(id,[{id:'remote',serverId:'server-one',mediaType:'image/png',size:imageBytes.length}]),raw=`Original\n\n![Image](${photoReference(old.documentId,'remote')})`;await incoming(metadata,raw);let calls=0;const downloader=async(need:any)=>{calls++;assert.equal(need.serverId,calls===1?'server-one':'server-two');return new Blob([imageBytes],{type:'image/png'});};
 const first=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:raw,current,now,downloadOriginal:downloader}),firstMarker=(await getSnapshot(first.receipt.imageReceiptKeys![0]))!,files=await listLocalBlobs(scope.accountId,scope.spaceId),asset=imageIds(first.draft.content as PaperDocument)[0];assert.equal(files.length,1);await putDraft({...old,baseVersion:8,content:{photos:[{id:'remote',serverId:'server-two',mediaType:'image/png',size:imageBytes.length}]}});
 const second=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:raw,current,now,downloadOriginal:downloader});assert.equal(calls,2);assert.deepEqual(imageIds(second.draft.content as PaperDocument),[asset]);assert.equal((second.draft.content as PaperDocument).assets.length,1);assert.equal(second.receipt.imageBindings![0].source.serverId,'server-two');assert.equal(second.receipt.imageReceiptKeys!.length,2);assert.deepEqual(await getSnapshot(firstMarker.key),firstMarker);assert.deepEqual(await listLocalBlobs(scope.accountId,scope.spaceId),files);const latest=(await getSnapshot(second.receipt.imageReceiptKeys![1]))!;assert.notEqual(latest.key,firstMarker.key);assert.equal(latest.value.remoteOriginals[0].serverId,'server-two');assert.equal(latest.value.remoteOriginals[0].sha256,firstMarker.value.remoteOriginals[0].sha256);
 const replay=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:raw,current,now});assert.equal(replay.changed,false);assert.equal(calls,2);assert.deepEqual(imageIds(replay.draft.content as PaperDocument),[asset]);assert.deepEqual(await listLocalBlobs(scope.accountId,scope.spaceId),files);
});

// A read-only reopen must not rewrite only a receipt timestamp. The exact
// source CAS remains required even when the resulting transaction has no writes.
test('Repeated unchanged legacy observation preserves every receipt byte and still checks fresh metadata CAS',async()=>{
 const id='qa-bridge-observation-noop';await seed(id);const first=await reconcilePaperLegacy({noteId:id,scope,incomingMarkdown:'Original',metadataAuthority:'indexeddb',current,now});
 const snapshot=await getSnapshot(paperLegacyReceiptKey(scope,id)),draft=await getDraft(first.draft),snapshots=await listSnapshots(scope.accountId,scope.spaceId),queue=await listMutations(scope.accountId,scope.spaceId),files=await listLocalBlobs(scope.accountId,scope.spaceId);
 const plan=await preflightPaperLegacy({noteId:id,scope,incomingMarkdown:'Original',metadataAuthority:'indexeddb',current,now:'2026-10-15T19:00:00.000Z'});
 assert.equal(plan.changed,false);assert.equal(plan.commit.snapshots.length,0,'An identical admitted observation must not persist a newer timestamp');assert.equal(plan.commit.drafts.length,0);assert.equal(plan.commit.blobs.length,0);assert.deepEqual(plan.receiptRow,snapshot);assert.equal(plan.receipt.observedAt,first.receipt.observedAt);assert.ok(plan.commit.draftChecks.length>0);assert.ok(plan.commit.snapshotChecks.length>0);
 await commitPaperLegacyPreflight(plan,current);assert.deepEqual(await getDraft(first.draft),draft);assert.deepEqual(await listSnapshots(scope.accountId,scope.spaceId),snapshots);assert.deepEqual(await listMutations(scope.accountId,scope.spaceId),queue);assert.deepEqual(await listLocalBlobs(scope.accountId,scope.spaceId),files);
 const stale=await preflightPaperLegacy({noteId:id,scope,incomingMarkdown:'Original',metadataAuthority:'indexeddb',current,now:'2026-10-15T20:00:00.000Z'}),metadata=await getDraft({...scope,type:'notesMarkdown',documentId:id});assert.ok(metadata);await incoming(metadata,'New external contribution');
 await assert.rejects(()=>commitPaperLegacyPreflight(stale,current));assert.deepEqual(await getDraft(first.draft),draft);assert.deepEqual(await listSnapshots(scope.accountId,scope.spaceId),snapshots);assert.deepEqual(await listMutations(scope.accountId,scope.spaceId),queue);
});
